let effect=0, stream, running=false, mode='single', recorder, chunks=[], face=null, segment=null, segmentationBusy=false, faceBusy=false, faceModel=null, segmenter=null, lastTime=-1, lastMask=0, lastFace=0;
const raw=document.createElement('canvas');raw.width=W;raw.height=H;const rctx=raw.getContext('2d',{willReadFrequently:true});
const layer=document.createElement('canvas');layer.width=W;layer.height=H;const lctx=layer.getContext('2d',{willReadFrequently:true});
const trail=document.createElement('canvas');trail.width=W;trail.height=H;const tctx=trail.getContext('2d');const scratch=document.createElement('canvas');scratch.width=W;scratch.height=H;const scratchCtx=scratch.getContext('2d');let previous=null;
const maskCanvas=document.createElement('canvas');maskCanvas.width=W;maskCanvas.height=H;const maskCtx=maskCanvas.getContext('2d',{willReadFrequently:true});let stableMask=null;
const previewCanvas=document.createElement('canvas');previewCanvas.width=W;previewCanvas.height=H;const previewCtx=previewCanvas.getContext('2d',{willReadFrequently:true});let lastPreview=0;const previewPhoto=new Image();previewPhoto.src='assets/preview.jpg';previewPhoto.onload=()=>{if(!running){cover(rctx,previewPhoto);updatePreviews(performance.now())}};
const bgs=[1,2,3].map(i=>{const im=new Image();im.src=`assets/bg${i}.jpg`;return im});const logo=new Image();logo.src='logo.svg';
const tiles=names.map((name,i)=>{let b=document.createElement('button');b.className='effect'+(!i?' active':'');b.innerHTML=`<canvas width="320" height="190"></canvas><span>${name}</span>`;b.onclick=()=>{effect=i;effects.classList.add('hidden');$('#toggle').textContent='Эффекты';tiles.forEach((x,n)=>x.classList.toggle('active',n===i))};b.style.order=([4,0,1,2,3,5,6,7,8][i]);effects.append(b);return b});
function cover(c,img,vertical=.5){let iw=img.videoWidth||img.width,ih=img.videoHeight||img.height;if(!iw||!ih)return;let scale=Math.max(W/iw,H/ih),sw=W/scale,sh=H/scale;c.drawImage(img,(iw-sw)/2,(ih-sh)*vertical,sw,sh,0,0,W,H)}
async function models(){try{const {FaceLandmarker,FilesetResolver}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/+esm');let vision=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');faceModel=await FaceLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task',delegate:'GPU'},runningMode:'VIDEO',numFaces:1})}catch(e){console.warn('Face model:',e)} }
function initSegment(){if(!window.SelfieSegmentation){setTimeout(()=>{if(running&&!segmenter)initSegment()},1000);return;}try{segmenter=new SelfieSegmentation({locateFile:f=>'https://cdn.jsdelivr.net/npm/@mediapipe/selfie_segmentation/'+f});segmenter.setOptions({modelSelection:1});segmenter.onResults(result=>{maskCtx.clearRect(0,0,W,H);maskCtx.filter='blur(4px)';maskCtx.drawImage(result.segmentationMask,0,0,W,H);maskCtx.filter='none';const mask=maskCtx.getImageData(0,0,W,H), pixels=mask.data;if(!stableMask)stableMask=new Float32Array(W*H).fill(-1);for(let i=0,j=0;i<pixels.length;i+=4,j++){let value=pixels[i]/255;stableMask[j]=stableMask[j]<0?value:stableMask[j]*.7+value*.3;let t=Math.max(0,Math.min(1,(stableMask[j]-.47)/.09));pixels[i]=pixels[i+1]=pixels[i+2]=255;pixels[i+3]=Math.round(255*t*t*(3-2*t))}maskCtx.putImageData(mask,0,0);lctx.clearRect(0,0,W,H);lctx.drawImage(maskCanvas,0,0);lctx.globalCompositeOperation='source-in';lctx.drawImage(result.image,0,0,W,H);lctx.globalCompositeOperation='source-over';segment=true;segmentationBusy=false})}catch(e){console.warn(e)}}
async function start(){try{stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'},audio:false});video.srcObject=stream;await video.play();$('#message').classList.add('hidden');running=true;initSegment();models();requestAnimationFrame(draw)}catch(e){$('#message p').textContent='Не удалось включить камеру';$('#message small').textContent='Проверь разрешение браузера и открой сайт по HTTPS или localhost.'}}
$('#start').onclick=start;
function draw(now){if(!running)return;requestAnimationFrame(draw);if(video.readyState<2)return;rctx.save();rctx.translate(W,0);rctx.scale(-1,1);cover(rctx,video);rctx.restore();
 if(((effect>=1&&effect<=3)||!effects.classList.contains('hidden'))&&segmenter&&!segmentationBusy&&now-lastMask>65){segmentationBusy=true;lastMask=now;segmenter.send({image:raw}).catch(()=>{segmentationBusy=false})}
 if((effect===0||effect===8||!effects.classList.contains('hidden'))&&faceModel&&now-lastFace>75&&!faceBusy&&video.currentTime!==lastTime){try{lastTime=video.currentTime;lastFace=now;face=faceModel.detectForVideo(video,now).faceLandmarks[0]||null}catch(e){console.warn(e)}}
 render(ctx,effect,now);if(!effects.classList.contains('hidden')&&now-lastPreview>500){lastPreview=now;updatePreviews(now)}}
function updatePreviews(now){tiles.forEach((tile,i)=>{let c=tile.querySelector('canvas').getContext('2d');if(running&&i===effect)c.drawImage(screen,0,0,320,190);else{render(previewCtx,i,now,true);c.drawImage(previewCanvas,0,0,320,190)}})}
function render(c,e,now,preview=false){c.clearRect(0,0,W,H);if(e>=1&&e<=3){cover(c,bgs[e-1],e===1?.85:.5);if(segment)c.drawImage(layer,0,0);else{c.globalAlpha=.5;c.drawImage(raw,0,0);c.globalAlpha=1}finishPoster(c)}else{c.drawImage(raw,0,0)}
 if(e===0){let x=W*.5,y=H*.18,rx=W*.13,size=65;if(face){let p=face[10];x=(1-p.x)*W;y=Math.max(38,p.y*H-55);rx=Math.max(70,Math.abs(face[234].x-face[454].x)*W*.75);size=Math.max(45,Math.min(100,rx*.48))}if(logo.complete){for(let i=0;i<3;i++){let a=now*.00065+i*Math.PI*2/3,px=x+Math.cos(a)*rx,py=y+Math.sin(a)*rx*.24;c.save();c.translate(px,py);c.drawImage(logo,-size/2,-size/2,size,size);c.restore()}}}
 if(e===4) applyChrome(c);
 if(e===5&&preview){c.save();c.globalAlpha=.3;c.globalCompositeOperation='screen';c.filter='hue-rotate(130deg) saturate(4)';c.drawImage(raw,-25,0,W,H);c.restore()}
 if(e===5&&!preview){let frame=rctx.getImageData(0,0,W,H);if(previous){let data=frame.data, old=previous.data;let diff=tctx.createImageData(W,H);for(let i=0;i<data.length;i+=4){let d=Math.abs(data[i]-old[i])+Math.abs(data[i+1]-old[i+1])+Math.abs(data[i+2]-old[i+2]);if(d>70){let palette=[[255,65,0],[0,224,255],[255,30,150],[255,230,0],[35,55,255]];let phase=now/1100+(i/4%W)/260, index=Math.floor(phase)%palette.length, blend=phase-Math.floor(phase);blend=blend*blend*(3-2*blend);let a=palette[index],b=palette[(index+1)%palette.length];diff.data[i]=a[0]+(b[0]-a[0])*blend;diff.data[i+1]=a[1]+(b[1]-a[1])*blend;diff.data[i+2]=a[2]+(b[2]-a[2])*blend;diff.data[i+3]=Math.min(220,d)}}tctx.globalCompositeOperation='destination-out';tctx.fillStyle='rgba(0,0,0,.025)';tctx.fillRect(0,0,W,H);tctx.globalCompositeOperation='source-over';scratchCtx.putImageData(diff,0,0);tctx.drawImage(scratch,0,0)}previous=frame;c.globalAlpha=.8;c.drawImage(trail,0,0);c.globalAlpha=1}
 if(e===6||e===7){let image=c.getImageData(0,0,W,H),d=image.data;for(let i=0;i<d.length;i+=4){let light=(d[i]*.299+d[i+1]*.587+d[i+2]*.114)/255;if(e===6){let level=light*12,edge=Math.abs((level+.5-Math.floor(level+.5))-.5),t=Math.max(0,Math.min(1,(edge-.035)/(.16-.035))),line=1-t*t*(3-2*t),v=(.045+line*.95);let palette=[[255,65,0],[0,224,255],[255,30,150],[255,230,0],[35,55,255]],phase=light*(palette.length-1),index=Math.min(palette.length-2,Math.floor(phase)),blend=phase-index;blend=blend*blend*(3-2*blend);let a=palette[index],b=palette[index+1];d[i]=(a[0]+(b[0]-a[0])*blend)*v;d[i+1]=(a[1]+(b[1]-a[1])*blend)*v;d[i+2]=(a[2]+(b[2]-a[2])*blend)*v}else{let v=Math.max(0,Math.min(1,((1-light)-.36)*2.15));v=v*v*(3-2*v);d[i]=v*135;d[i+1]=v*205;d[i+2]=v*255}}c.putImageData(image,0,0);if(e===7){scratchCtx.clearRect(0,0,W,H);scratchCtx.drawImage(c.canvas,0,0);c.save();c.globalCompositeOperation='screen';c.globalAlpha=.48;c.filter='blur(10px)';c.drawImage(scratch,0,0);c.restore()}}
 if(e===8&&face){let regions=[[33,133],[362,263],[61,291]];for(let [a,b] of regions){let mouth=a===61,x=(1-(face[a].x+face[b].x)/2)*W,y=mouth?(face[0].y+face[17].y)/2*H:(face[a].y+face[b].y)/2*H,rx=Math.max(18,Math.abs(face[a].x-face[b].x)*W*.82),ry=mouth?Math.max(14,Math.abs(face[17].y-face[0].y)*H*.75+5):rx*.77;if(mouth){let noseBottom=face[2].y*H;y=Math.max(y,noseBottom+ry*1.5+2)}scratchCtx.clearRect(0,0,W,H);scratchCtx.globalCompositeOperation='source-over';scratchCtx.drawImage(raw,x-rx,y-ry,rx*2,ry*2,x-rx*1.5,y-ry*1.5,rx*3,ry*3);scratchCtx.globalCompositeOperation='destination-in';scratchCtx.save();scratchCtx.translate(x,y);scratchCtx.scale(rx*1.5,ry*1.5);let gradient=scratchCtx.createRadialGradient(0,0,.48,0,0,1);gradient.addColorStop(0,'rgba(0,0,0,1)');gradient.addColorStop(1,'rgba(0,0,0,0)');scratchCtx.fillStyle=gradient;scratchCtx.fillRect(-1,-1,2,2);scratchCtx.restore();scratchCtx.globalCompositeOperation='source-over';c.drawImage(scratch,0,0)}}}
$('#toggle').onclick=()=>{effects.classList.toggle('hidden');$('#toggle').textContent=effects.classList.contains('hidden')?'Эффекты':'Готово';if(!effects.classList.contains('hidden'))updatePreviews(performance.now())};
for(const m of ['single','quad','movie'])$('#'+m).onclick=()=>{mode=m;document.querySelectorAll('.modes button').forEach(b=>b.classList.remove('selected'));$('#'+m).classList.add('selected')};
const wait=ms=>new Promise(r=>setTimeout(r,ms));async function countdown(){for(let n=3;n>0;n--){$('#count').textContent=n;await wait(700)}$('#count').textContent=''}
function addPhoto(url,type='image'){const el=document.createElement(type==='image'?'img':'video');el.src=url;if(type==='video')el.controls=true;el.title='Нажми, чтобы скачать';el.onclick=()=>{let a=document.createElement('a');a.href=url;a.download=`photo-booth-${Date.now()}.${type==='image'?'png':'webm'}`;a.click()};$('#empty')?.remove();$('#film').prepend(el)}
$('#shutter').onclick=async()=>{if(!running){start();return}if(mode==='movie'){if(recorder?.state==='recording'){recorder.stop();$('#shutter').classList.remove('recording');return}chunks=[];recorder=new MediaRecorder(screen.captureStream(25));recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>addPhoto(URL.createObjectURL(new Blob(chunks,{type:'video/webm'})),'video');recorder.start();$('#shutter').classList.add('recording');return}await countdown();if(mode==='single')addPhoto(screen.toDataURL('image/png'));else{let out=document.createElement('canvas');out.width=W*2;out.height=H*2;let o=out.getContext('2d');for(let i=0;i<4;i++){o.drawImage(screen,(i%2)*W,Math.floor(i/2)*H);if(i<3)await wait(800)}addPhoto(out.toDataURL('image/png'))}};

const reviews=[["4315","4313","4311"],["4314","4312","4310"]], reviewIndex=[0,0],reviewSides=[...document.querySelectorAll(".review-side")],reviewDialog=document.querySelector(".review-dialog");
function showReview(side){let box=reviewSides[side],id=reviews[side][reviewIndex[side]];box.querySelector("img").src=`assets/reviews/IMG_${id}.jpg`;box.querySelector(".review-count").textContent=`${reviewIndex[side]+1} / ${reviews[side].length}`;}
reviewSides.forEach((box,side)=>{showReview(side);box.querySelector(".prev").onclick=()=>{reviewIndex[side]=(reviewIndex[side]+2)%3;showReview(side)};box.querySelector(".next").onclick=()=>{reviewIndex[side]=(reviewIndex[side]+1)%3;showReview(side)};box.querySelector(".review-card").onclick=()=>{reviewDialog.querySelector("img").src=box.querySelector("img").src;reviewDialog.showModal()}});document.querySelector(".close-review").onclick=()=>reviewDialog.close();reviewDialog.addEventListener("click",e=>{if(e.target===reviewDialog)reviewDialog.close()});setInterval(()=>{if(reviewDialog.open||document.hidden)return;reviewSides.forEach((box,side)=>{if(box.matches(":hover")||box.contains(document.activeElement))return;reviewIndex[side]=(reviewIndex[side]+1)%3;showReview(side)})},30000);

const mobileReviews=document.querySelector(".mobile-reviews-dialog"),mobileReviewItems=["4315","4314","4313","4312","4311","4310"];let mobileReviewIndex=0;function showMobileReview(){mobileReviews.querySelector("img").src=`assets/reviews/IMG_${mobileReviewItems[mobileReviewIndex]}.jpg`;mobileReviews.querySelector(".mobile-review-count").textContent=`${mobileReviewIndex+1} / ${mobileReviewItems.length}`;mobileReviews.querySelector(".mobile-review-scroll").scrollTop=0}document.querySelector(".mobile-reviews-button").onclick=()=>{showMobileReview();mobileReviews.showModal()};document.querySelector(".mobile-reviews-close").onclick=()=>mobileReviews.close();document.querySelector(".mobile-review-prev").onclick=()=>{mobileReviewIndex=(mobileReviewIndex+mobileReviewItems.length-1)%mobileReviewItems.length;showMobileReview()};document.querySelector(".mobile-review-next").onclick=()=>{mobileReviewIndex=(mobileReviewIndex+1)%mobileReviewItems.length;showMobileReview()};mobileReviews.addEventListener("click",e=>{if(e.target===mobileReviews)mobileReviews.close()});
